import re
from typing import Dict

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    lines = text.splitlines()
    result: Dict[str, Dict[str, str]] = {}
    current_section: Dict[str, str] = {}
    section_stack: list[str] = []
    default_section: Dict[str, str] = {}
    in_section = False

    def strip_comments(line: str) -> str:
        if '"' not in line:
            return re.split(r'\s*(?<!\\)[;#]', line)[0].rstrip()
        parts = re.split(r'(?<!\\)"', line)
        for i in range(1, len(parts), 2):
            parts[i] = re.split(r'\s*(?<!\\)[;#]', parts[i])[0]
        return ''.join(parts).rstrip()

    def interpolate(value: str, section_name: str, seen: set[str] = None) -> str:
        if seen is None:
            seen = set()
        if value in seen:
            raise ValueError("Interpolation cycle detected")
        seen.add(value)
        def replace(match: re.Match) -> str:
            key_ref = match.group(1)
            if ':' in key_ref:
                ref_section, ref_key = key_ref.split(':', 1)
                if ref_section not in result:
                    raise KeyError(f"Section {ref_section} not found")
                if ref_key not in result[ref_section]:
                    raise KeyError(f"Key {ref_key} not found in section {ref_section}")
                return interpolate(result[ref_section][ref_key], ref_section, seen)
            else:
                if key_ref not in current_section:
                    if key_ref not in default_section:
                        raise KeyError(f"Key {key_ref} not found in section {section_name}")
                    return interpolate(default_section[key_ref], 'DEFAULT', seen)
                return interpolate(current_section[key_ref], section_name, seen)
        value = re.sub(r'\${(.*?)}', replace, value)
        seen.remove(value)
        return value

    for line_no, line in enumerate(lines, 1):
        line = strip_comments(line).rstrip()
        if not line or line.isspace():
            continue
        stripped_line = line.strip()
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            if not in_section and section_stack:
                raise ValueError(f"Malformed line {line_no}: {line}")
            section_name = stripped_line[1:-1].strip()
            if section_name == 'DEFAULT':
                current_section = default_section
            else:
                current_section = result.setdefault(section_name, {})
                for key, value in default_section.items():
                    if key not in current_section:
                        current_section[key] = value
            in_section = True
            section_stack.append(section_name)
            continue
        if not in_section:
            raise ValueError(f"Key outside section at line {line_no}: {line}")
        if line.startswith(' ') or line.startswith('\t'):
            if not section_stack:
                raise ValueError(f"Malformed continuation line {line_no}: {line}")
            last_section = section_stack[-1]
            last_key = next(reversed(result[last_section]), None)
            if last_key is None:
                raise ValueError(f"Malformed continuation line {line_no}: {line}")
            result[last_section][last_key] += '\n' + line.strip()
            continue
        match = re.match(r'\s*([^\s=:#]+)\s*[:=]\s*(.*)\s*$', line)
        if not match:
            raise ValueError(f"Malformed line {line_no}: {line}")
        key, value = match.groups()
        key = key.strip().lower()
        if value.startswith('"') and value.endswith('"'):
            value = value[1:-1].replace('\\"', '"')
        else:
            value = value.strip()
        if section_stack:
            current_section[key] = value
        else:
            default_section[key] = value

    for section_name, section in result.items():
        for key, value in section.items():
            try:
                result[section_name][key] = interpolate(value, section_name)
            except (KeyError, ValueError) as e:
                raise ValueError(f"Error interpolating key {key} in section {section_name}: {e}")

    if 'DEFAULT' in result:
        del result['DEFAULT']

    return result
