from collections import OrderedDict
from typing import Any, Callable, Dict, Optional

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock: Callable[[], float]):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache: OrderedDict[Any, tuple[Any, float]] = OrderedDict()
        self.stats: Dict[str, int] = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

    def _remove_expired(self) -> None:
        now = self.clock()
        expired = [key for key, (_, expiry) in self.cache.items() if expiry <= now]
        for key in expired:
            del self.cache[key]
            self.stats["expirations"] += 1

    def put(self, key: Any, value: Any) -> None:
        if self.capacity == 0:
            return

        self._remove_expired()

        now = self.clock()
        expiry = now + self.ttl

        if key in self.cache:
            self.cache.move_to_end(key)
        elif len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)
            self.stats["evictions"] += 1

        self.cache[key] = (value, expiry)

    def get(self, key: Any, default: Optional[Any] = None) -> Any:
        if self.capacity == 0:
            self.stats["misses"] += 1
            return default

        self._remove_expired()

        now = self.clock()
        if key in self.cache:
            value, expiry = self.cache[key]
            if expiry > now:
                self.cache.move_to_end(key)
                self.stats["hits"] += 1
                return value
            else:
                del self.cache[key]
                self.stats["expirations"] += 1

        self.stats["misses"] += 1
        return default

    def __len__(self) -> int:
        now = self.clock()
        return sum(1 for _, expiry in self.cache.values() if expiry > now)

    def stats(self) -> Dict[str, int]:
        return self.stats.copy()
